                    os.unlink(temporary)
                except OSError:
                    pass

    def _without_expired_locked(self, now: float) -> tuple[dict[str, dict[str, Any]], bool]:
        live = {
            key: entry for key, entry in self.entries.items() if self._is_live(entry, now)
        }
        return live, len(live) != len(self.entries)

