    def kv_server(self) -> KVServer:
        return self.server  # type: ignore[return-value]

    def log_message(self, fmt: str, *args: Any) -> None:
        print(
            f"{self.client_address[0]} - {fmt % args}",
            file=sys.stderr,
            flush=True,
        )

